SELECT 
FROM agent_trace_event
WHERE session_id = #{sessionId}

    AND event_type = #{type}


    AND call_id = #{callId}


    AND step_no = #{step}

ORDER BY seq ASC
LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*)
FROM agent_trace_event
WHERE session_id = #{sessionId}

    AND event_type = #{type}


    AND call_id = #{callId}


    AND step_no = #{step}

SELECT 
FROM agent_trace_event
WHERE session_id = #{sessionId}
  AND seq > #{afterSeq}
ORDER BY seq ASC
LIMIT #{size}

SELECT COALESCE(MAX(turn_no), 0)
FROM agent_trace_event
WHERE session_id = #{sessionId}
